 if(boards){const b=+$('boardSize').value;ctx.strokeStyle='#c47049';ctx.lineWidth=Math.max(1,cell*.08);ctx.setLineDash([cell*.4,cell*.25]);for(let x=b;x<w;x+=b){ctx.beginPath();ctx.moveTo(pad+x*cell,pad);ctx.lineTo(pad+x*cell,pad+h*cell);ctx.stroke()}for(let y=b;y<h;y+=b){ctx.beginPath();ctx.moveTo(pad,pad+y*cell);ctx.lineTo(pad+w*cell,pad+y*cell);ctx.stroke()}ctx.setLineDash([])}
