function parseCSV(text){const rows=[];let row=[],field='',quote=false;for(let i=0;i<text.length;i++){const c=text[i];if(c==='"'){if(quote&&text[i+1]==='"'){field+='"';i++}else quote=!quote}else if(c===','&&!quote){row.push(field.trim());field=''}else if((c==='\n'||c==='\r')&&!quote){if(c==='\r'&&text[i+1]==='\n')i++;row.push(field.trim());if(row.some(Boolean))rows.push(row);row=[];field=''}else field+=c}if(field||row.length){row.push(field.trim());rows.push(row)}if(quote)throw Error('CSV 引号未闭合');const headers=rows.shift()?.map(x=>x.replace(/^\uFEFF/,'').toLowerCase());if(!headers?.includes('code')||!headers.includes('hex'))throw Error('CSV 需要 code,hex 表头');return rows.map(r=>Object.fromEntries(headers.map((h,i)=>[h,r[i]||''])))}
function validatePalette(p){if(!Array.isArray(p)||!p.length||p.length>512)throw Error('色卡需为包含 1–512 色的数组');const codes=new Set();return p.map(c=>{if(typeof c.code!=='string'||!c.code.trim()||c.code.length>16||!/^#[\da-f]{6}$/i.test(c.hex))throw Error('每种颜色需要 code（1–16 字符）与 #RRGGBB 格式 hex');if(codes.has(c.code))throw Error('色卡中存在重复色号：'+c.code);codes.add(c.code);return{code:c.code,name:typeof c.name==='string'?c.name.slice(0,100):c.code,hex:c.hex.toUpperCase()}})}
async function importPalette(file){if(!file)return;try{if(file.size>1024*1024)throw Error('色卡文件不能超过 1 MB');const text=await file.text(),p=validatePalette(file.name.toLowerCase().endsWith('.csv')?parseCSV(text):JSON.parse(text));palettes.custom=p;let opt=$('palette').querySelector('[value="custom"]');if(!opt){opt=document.createElement('option');opt.value='custom';$('palette').append(opt)}opt.textContent=`自定义 · ${p.length} 色`;$('palette').value='custom';toast('色卡已导入');generate()}catch(e){toast('导入失败：'+e.message)}}
async function importProject(file){if(!file)return;try{if(file.size>3*1024*1024)throw Error('工程文件不能超过 3 MB');const p=JSON.parse(await file.text());if(!['doudou-beads-v1','bead-studio-v2'].includes(p.format))throw Error('不是bead studio工程文件');if(![p.width,p.height].every(n=>Number.isInteger(n)&&n>=1&&n<=256))throw Error('工程尺寸无效');const palette=validatePalette(p.palette);if(!Array.isArray(p.indices)||p.indices.length!==p.width*p.height||p.indices.some(i=>!Number.isInteger(i)||i< -1||i>=palette.length))throw Error('工程颜色索引无效');++requestID;worker?.terminate();clearTimeout(timer);title=typeof p.title==='string'?p.title.slice(0,100):'导入工程';$('paperTitle').textContent=title;$('width').value=p.width;$('height').value=p.height;$('aspect').checked=false;if([2.6,5].includes(p.beadSize))$('beadSize').value=p.beadSize;if([29,50,52].includes(p.boardSize))$('boardSize').value=p.boardSize;const counts=palette.map(()=>0);p.indices.forEach(i=>{if(i>=0)counts[i]++});const {preparePalette}=await import('./engine.mjs?v=3');palettes.custom=palette;if(!$('palette').querySelector('[value="custom"]')){const opt=document.createElement('option');opt.value='custom';$('palette').append(opt)}$('palette').querySelector('[value="custom"]').textContent=`自定义 · ${palette.length} 色`;$('palette').value='custom';// Reconstruct a lossless source so subsequent size changes work.
 const data=new Uint8ClampedArray(p.width*p.height*4);p.indices.forEach((v,i)=>{if(v<0)return;const rgb=[1,3,5].map(j=>parseInt(palette[v].hex.slice(j,j+2),16));data.set([...rgb,255],i*4)});source={data,sw:p.width,sh:p.height};const c=document.createElement('canvas');c.width=p.width;c.height=p.height;c.getContext('2d').putImageData(new ImageData(data,p.width,p.height),0,0);if(sourceURL.startsWith('blob:'))URL.revokeObjectURL(sourceURL);sourceURL=c.toDataURL();$('sourceThumb').src=sourceURL;$('originalView').src=sourceURL;$('compareSource').src=sourceURL;$('mode').value='pixel';$('maxColors').value=Math.min(64,Math.max(2,palette.length));$('colorValue').textContent=$('maxColors').value;zoom=1;syncPresets();applyResult({width:p.width,height:p.height,palette:preparePalette(palette),indices:Int16Array.from(p.indices),counts,total:counts.reduce((a,b)=>a+b,0),mode:'工程',elapsed:0});$('exportDialog').close();toast('工程已恢复')}catch(e){toast('导入失败：'+e.message)}}
